package ru.ileech.ndicamera;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.content.res.Configuration;
import android.graphics.RectF;
import android.os.*;
import android.view.*;
import java.lang.reflect.*;
import java.util.*;

/** Device-side integration checks; no test hooks are shipped in the application. */
public class SmokeInstrumentation extends Instrumentation {
 private MainActivity activity;private CameraController camera;private CameraHud hud;
 private Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 private void require(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 private void ui(Runnable task){Throwable[] failure={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){failure[0]=e;}});waitForIdleSync();if(failure[0]!=null)throw new AssertionError(failure[0]);}
 private void settle()throws Exception{Thread.sleep(350);waitForIdleSync();}
 private void ready()throws Exception{for(int n=0;n<100&&!camera.ready;n++)Thread.sleep(100);require(camera.ready,"Camera2 not ready: "+camera.state);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();StringBuilder checks=new StringBuilder();try{
  activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();camera=(CameraController)field(activity,"camera");hud=(CameraHud)field(activity,"hud");require(camera!=null&&hud!=null,"Camera initialization");ready();checks.append("Camera2 preview READY\n");geometry();checks.append("producer transforms: no double rotation, uniform pixel scale, GL readback flip, 4 rotations\n");
  ui(()->activity.action("mute"));ui(()->activity.action("start"));settle();StreamSession stream=(StreamSession)field(activity,"stream");require(stream!=null&&StreamSession.running,"NDI START");require(stream.muted,"initial MUTE");
  ui(()->activity.action("mute"));settle();require(!stream.muted&&field(stream,"record")!=null,"UNMUTE starts microphone");checks.append("MUTE -> START -> UNMUTE opens AudioRecord\n");
  ui(()->activity.action("mute"));require(stream.muted,"MUTE while streaming");ui(()->activity.action("start"));require(!StreamSession.running,"STOP tears down sender");checks.append("NDI START/STOP and audio teardown\n");
  StreamSession lazy=new StreamSession(getTargetContext(),"NDI Camera audio regression",false,true);require(field(lazy,"record")==null,"muted session has no AudioRecord");lazy.enableMicrophone();require(field(lazy,"record")!=null,"late AudioRecord creation");lazy.muted=false;settle();require(lazy.error.isEmpty(),"late microphone error: "+lazy.error);lazy.close();checks.append("lazy microphone creation after initially silent session\n");
  ui(()->activity.action("hide"));require(hud.hidden,"HIDE");ui(()->activity.action("restore"));require(!hud.hidden,"HUD restore");ui(()->activity.action("grid"));require(!hud.grid,"grid toggle");ui(()->activity.action("scopes"));require(hud.scopes,"scopes toggle");checks.append("HIDE/restore/grid/scopes\n");
  float previous=camera.ev;ui(()->{long t=SystemClock.uptimeMillis();hud.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,hud.getWidth()*.5f,hud.getHeight()*.5f,0));});Thread.sleep(700);ui(()->{long t=SystemClock.uptimeMillis();hud.dispatchTouchEvent(MotionEvent.obtain(t-700,t,MotionEvent.ACTION_MOVE,hud.getWidth()*.5f,hud.getHeight()*.5f-180,0));hud.dispatchTouchEvent(MotionEvent.obtain(t-700,t+20,MotionEvent.ACTION_UP,hud.getWidth()*.5f,hud.getHeight()*.5f-180,0));});settle();require(camera.ev>previous,"hold/swipe EV");if(camera.supportsAeLock())require(camera.aeLock,"hold locks AE");if(camera.supportsAf())require(camera.afLock,"hold locks AF");checks.append("hold + swipe locks AE/AF and changes EV\n");
  ui(()->camera.zoom(camera.minZoom));settle();float before=camera.zoom;
  ui(()->{long t=SystemClock.uptimeMillis();float cx=hud.getWidth()*.5f,cy=hud.getHeight()*.5f;touch(t,t,MotionEvent.ACTION_DOWN,new float[]{cx-100},new float[]{cy});touch(t,t+20,MotionEvent.ACTION_POINTER_DOWN|(1<<8),new float[]{cx-100,cx+100},new float[]{cy,cy});for(int i=0;i<20;i++)touch(t,t+40+i*20,MotionEvent.ACTION_MOVE,new float[]{cx-100-i*14,cx+100+i*14},new float[]{cy,cy});touch(t,t+460,MotionEvent.ACTION_POINTER_UP|(1<<8),new float[]{cx-366,cx+366},new float[]{cy,cy});touch(t,t+480,MotionEvent.ACTION_UP,new float[]{cx-366},new float[]{cy});});settle();if(camera.maxZoom>camera.minZoom)require(camera.zoom>before,"pinch zoom before="+before+" after="+camera.zoom+" range="+camera.minZoom+".."+camera.maxZoom);checks.append("two-pointer pinch zoom\n");
  ui(()->activity.action("camera"));ready();settle();if(!camera.front.isEmpty())require(camera.mainFront,"front camera switch");ui(()->activity.action("light"));require(hud.frontLight,"front screen light");ui(()->activity.action("light"));require(!hud.frontLight,"front light off");checks.append("front camera + screen flash\n");
  ui(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));for(int n=0;n<50&&hud.getWidth()<hud.getHeight();n++)Thread.sleep(100);require(hud.getWidth()>hud.getHeight(),"landscape layout");settle();checkButtons();autoHud();insets(130,0,75,0);insets(0,0,145,70);insets(0,90,0,0);screenshot("landscape");checks.append("landscape: controls and rotated slider inside cutout/navigation safe bounds\n");
  ui(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));for(int n=0;n<50&&hud.getWidth()>hud.getHeight();n++)Thread.sleep(100);settle();checkButtons();autoHud();insets(0,90,0,120);screenshot("portrait");checks.append("portrait: MUTE/audio in bounds with navigation inset, header at 50 px\n");
  ui(()->activity.action("camera"));settle();if(!camera.concurrent())require(!camera.pip,"unsupported PIP rejected");checks.append("PIP capability fallback\n");
  autoHud();checks.append("automatic camera only; lens selector absent; centered 50px toolbar and 50px settings/camera gap"+"\n");
  result.putString("checks",checks.toString());result.putString("verdict","PASS");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("checks",checks.toString());result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
 private void screenshot(String name)throws Exception{android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();require(bitmap!=null,"screenshot "+name);require(name.equals("landscape")?bitmap.getWidth()>bitmap.getHeight():bitmap.getHeight()>bitmap.getWidth(),"screenshot orientation "+name);try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 private void insets(int left,int top,int right,int bottom)throws Exception{WindowInsets actual=hud.getRootWindowInsets();WindowInsets simulated=new WindowInsets.Builder().setInsetsIgnoringVisibility(WindowInsets.Type.systemBars(),android.graphics.Insets.of(left,top,right,bottom)).setInsets(WindowInsets.Type.systemBars(),android.graphics.Insets.NONE).setDisplayCutout(new DisplayCutout(android.graphics.Insets.of(left,top,0,0),left>0?new android.graphics.Rect(0,0,left,100):null,top>0?new android.graphics.Rect(hud.getWidth()/2-30,0,hud.getWidth()/2+30,top):null,null,null)).build();ui(()->hud.dispatchApplyWindowInsets(simulated));settle();ui(()->{require(hud.getPaddingLeft()==0&&hud.getPaddingTop()==0,"no duplicate FrameLayout padding");for(int i=0;i<hud.getChildCount();i++){View v=hud.getChildAt(i);if(v.getVisibility()!=View.VISIBLE)continue;RectF r=new RectF(0,0,v.getWidth(),v.getHeight());v.getMatrix().mapRect(r);r.offset(v.getLeft(),v.getTop());require(r.left>=left-.1f&&r.right<=hud.getWidth()-right+.1f&&r.bottom<=hud.getHeight()-bottom+.1f,"child outside safe bounds: "+v.getContentDescription()+" "+r);}View logo=null;for(int i=0;i<hud.getChildCount();i++)if(hud.getChildAt(i) instanceof android.widget.ImageView)logo=hud.getChildAt(i);require(logo!=null&&logo.getTop()==50,"header physical 50px");});checkButtons();autoHud();ui(()->hud.dispatchApplyWindowInsets(actual));settle();}
 @SuppressWarnings("unchecked") private void autoHud()throws Exception{Map<String,android.widget.Button> buttons=(Map<String,android.widget.Button>)field(hud,"buttons");ui(()->{require(!buttons.containsKey("lenses"),"no lens selector in either orientation");require(camera.active.physical==null,"automatic camera output");if(hud.getWidth()>hud.getHeight()){View first=buttons.get("grid"),last=buttons.get("hide"),settings=buttons.get("settings"),switcher=buttons.get("camera");int expected=(Integer)readHud("headerTop");for(android.graphics.Rect cutout:(List<android.graphics.Rect>)readHud("cutoutRects"))if(cutout.left<last.getRight()&&cutout.right>first.getLeft()&&cutout.top<expected+first.getHeight()&&cutout.bottom>expected)expected=Math.max(expected,cutout.bottom+4);require(first.getTop()==expected&&last.getTop()==expected,"landscape tools at 50px or below intersecting cutout");int left=(Integer)readHud("contentLeft"),right=(Integer)readHud("contentRight");require(Math.abs(first.getLeft()+last.getRight()-left-right)<=1,"toolbar centered in safe viewport");require(switcher.getTop()-settings.getBottom()==50,"camera 50px below settings");}});}
 private Object readHud(String name){try{return field(hud,name);}catch(Exception e){throw new RuntimeException(e);}}
 private void geometry(){for(int sensor:new int[]{0,90,180,270})for(boolean mirror:new boolean[]{false,true}){float[] producer=new float[16];android.opengl.Matrix.setIdentityM(producer,0);android.opengl.Matrix.translateM(producer,0,.5f,.5f,0);android.opengl.Matrix.rotateM(producer,0,sensor,0,0,1);android.opengl.Matrix.scaleM(producer,0,mirror?-1:1,-1,1);android.opengl.Matrix.translateM(producer,0,-.5f,-.5f,0);int nw=sensor%180==0?1280:720,nh=sensor%180==0?720:1280;float[] unchanged=PreviewTransform.matrix(producer,1280,720,0,nw,nh,false,1);for(int i=0;i<16;i++)require(Math.abs(unchanged[i]-producer[i])<.0001,"producer rotation applied exactly once");for(int display=0;display<4;display++)for(int[] output:new int[][]{{1080,2316},{2316,1080},{720,1280},{1280,720}}){float[] m=PreviewTransform.matrix(producer,1280,720,display,output[0],output[1],false,1),flipped=PreviewTransform.matrix(producer,1280,720,display,output[0],output[1],true,1);double dx=Math.hypot(m[0]*1280/output[0],m[1]*720/output[0]),dy=Math.hypot(m[4]*1280/output[1],m[5]*720/output[1]);require(Math.abs(dx-dy)<.0001,"no stretching: "+sensor+" / "+display);float[] a=new float[4],b=new float[4];android.opengl.Matrix.multiplyMV(a,0,m,0,new float[]{.2f,.7f,0,1},0);android.opengl.Matrix.multiplyMV(b,0,flipped,0,new float[]{.2f,.3f,0,1},0);require(Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])<.0001,"readback and preview agree");}}}
 private void checkButtons(){ui(()->{List<View> views=new ArrayList<>();for(int i=0;i<hud.getChildCount();i++){View v=hud.getChildAt(i);if(v instanceof android.widget.Button&&v.getVisibility()==View.VISIBLE)views.add(v);}for(int i=0;i<views.size();i++)for(int j=i+1;j<views.size();j++){View a=views.get(i),b=views.get(j);RectF x=new RectF(a.getLeft(),a.getTop(),a.getRight(),a.getBottom()),y=new RectF(b.getLeft(),b.getTop(),b.getRight(),b.getBottom());require(!RectF.intersects(x,y),"buttons overlap: "+a.getContentDescription()+" / "+b.getContentDescription());}});}
 private void touch(long down,long time,int action,float[] x,float[] y){MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[x.length];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[x.length];for(int i=0;i<x.length;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=x[i];coords[i].y=y[i];coords[i].pressure=1;coords[i].size=1;}MotionEvent e=MotionEvent.obtain(down,time,action,x.length,props,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);hud.dispatchTouchEvent(e);e.recycle();}
}
